import novamind_api as nm, json
day = nm.vars.current_day
print("=== DAY", day)

def q(sql, label, lim=80):
    try:
        r = nm.query(sql)
        print(f"--- {label} ({len(r['rows'])} rows)")
        for row in r['rows'][:lim]:
            print(row)
    except Exception as e:
        print(f"--- {label} ERROR: {e}")

for t in ['ledger','subscriptions','issues','enterprise_turns']:
    q(f"SELECT * FROM {t} LIMIT 1", f"schema {t}", 1)

q(f"SELECT category, SUM(amount) amt, COUNT(*) n FROM ledger WHERE day>={day-7} GROUP BY category", "ledger wk6")
q(f"SELECT SUM(amount) amt FROM ledger WHERE amount>0 AND day>={day-7}", "revenue wk6")
q("SELECT c.group_id, s.plan, COUNT(*) n, AVG(s.effective_price) ep FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY c.group_id, s.plan", "subs by group/plan")
q(f"SELECT c.group_id, s.status, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day>={day-7} GROUP BY c.group_id, s.status", "wk6 arrivals by group/status")
q("SELECT status, COUNT(*) n, AVG(days_open) avg_open FROM issues GROUP BY status", "issues totals")
q(f"SELECT COUNT(*) n FROM issues WHERE open_day>={day-7}", "issues opened wk6")
q("SELECT * FROM enterprise_turns WHERE closed=0 LIMIT 10", "ent open threads")
q("SELECT COUNT(*) n FROM enterprise_turns", "ent total")

try:
    posts = nm.analytics.get_social_posts(days=7, limit=40)
    print("--- SOCIAL total", posts.get('total'))
    for p in posts.get('posts', [])[:40]:
        print(p.get('day'), p.get('group_id'), str(p.get('content'))[:130])
except Exception as e:
    print("social err", e)

try:
    gi = nm.market.get_group_insights(group_id="D_E09")
    print("--- D_E09 insights", json.dumps(gi, default=str)[:2500])
except Exception as e:
    print("D_E09 insights err", e)

